fn in_row(py: i32, rowy: i32) -> i32 {
    if py >= rowy - 12 && py < rowy + 16 { 1 } else { 0 }
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    if host::display::state_get(5) == 0 {
        host::display::state_set(5, 1);
        host::display::state_set(0, 200);
        host::display::state_set(1, 80);
        host::display::state_set(2, 240);
    }
    let tx: i32 = 30;
    let tw: i32 = w - 160;
    let down: i32 = host::display::pointer_down();
    let px: i32 = host::display::pointer_x();
    let py: i32 = host::display::pointer_y();
    if down == 1 {
        let mut rel: i32 = (px - tx) * 255 / tw;
        if rel < 0 { rel = 0; }
        if rel > 255 { rel = 255; }
        if in_row(py, 80) == 1 { host::display::state_set(0, rel); }
        if in_row(py, 130) == 1 { host::display::state_set(1, rel); }
        if in_row(py, 180) == 1 { host::display::state_set(2, rel); }
    }
    let r: i32 = host::display::state_get(0);
    let g: i32 = host::display::state_get(1);
    let b: i32 = host::display::state_get(2);
    host::display::clear(0x101010);
    host::display::fill_rect(tx, 80, tw, 6, 0x401010);
    host::display::fill_rect(tx, 80, r * tw / 255, 6, 0xff4040);
    host::display::fill_rect(tx + r * tw / 255 - 4, 72, 8, 22, 0xffffff);
    host::display::fill_rect(tx, 130, tw, 6, 0x104010);
    host::display::fill_rect(tx, 130, g * tw / 255, 6, 0x40ff40);
    host::display::fill_rect(tx + g * tw / 255 - 4, 122, 8, 22, 0xffffff);
    host::display::fill_rect(tx, 180, tw, 6, 0x101040);
    host::display::fill_rect(tx, 180, b * tw / 255, 6, 0x4080ff);
    host::display::fill_rect(tx + b * tw / 255 - 4, 172, 8, 22, 0xffffff);
    let mix: i32 = (r << 16) | (g << 8) | b;
    host::display::fill_rect(w - 110, 70, 90, 120, mix);
    host::display::draw_number(30, 30, r, 0xff6060, 2);
    host::display::draw_number(110, 30, g, 0x60ff60, 2);
    host::display::draw_number(190, 30, b, 0x6080ff, 2);
    host::display::present();
}
